import { getTestData } from '../utils/CommonMethods.js';
export class LoginPage {
  constructor(page) { this.page = page; this.username = page.getByPlaceholder('Username'); this.password = page.getByPlaceholder('Password'); this.loginButton = page.getByRole('button', { name: 'Login' }); this.inventoryHeading = page.getByText('Products', { exact: true }); }
  async open() { await this.page.goto('/'); }
  async login(username, password) { await this.username.fill(username); await this.password.fill(password); await this.loginButton.click(); }
  async loginWithValidCredentials() { const user = getTestData().validUser; await this.login(user.username, user.password); }
}
